# Приводим список к порядку номеров и проверяем полноту.
TASKS.sort(key=lambda task: task["num"])
assert [task["num"] for task in TASKS] == list(range(1, 28)), "Должно быть ровно 27 заданий"

TASK_BY_NUM = {task["num"]: task for task in TASKS}

for section_key, section in TASK_SECTIONS.items():
    for num in section["tasks"]:
        assert TASK_BY_NUM[num]["section"] == section_key, f"Задание {num}: неверный раздел"
    assert sum(2 if num in (26, 27) else 1 for num in section["tasks"]) == section["points"], (
        f"Раздел {section_key}: не сходится сумма баллов"
    )
